parameters.jsCode:
// Response shape from fetch-result-object isn't confirmed yet for this agent — handle the likely variants defensively.
const res = $json;
let candidates = res;

if (res && res.resultObject !== undefined) {
  candidates = res.resultObject;
}
if (typeof candidates === 'string') {
  try { candidates = JSON.parse(candidates); } catch (e) { candidates = []; }
}
if (candidates && !Array.isArray(candidates)) {
  candidates = candidates.data || candidates.rows || candidates.results || [];
}
if (!Array.isArray(candidates)) candidates = [];

return candidates.map((c) => ({ json: c }));

